  (id,reference_id,reference_title,title,keywords,sort_order,is_published)
values ('antihypertensive-bolus','antihypertensive-dosing','Antihypertensive Dosing','IV bolus chart',array['antihypertensive','antihypertensives','hypertension','HTN','high blood pressure','BP','adult','IV','intravenous','perioperative','periop','postoperative','PACU','bolus','push','labetalol','Trandate','hydralazine','Apresoline','esmolol','Brevibloc','metoprolol','Lopressor','beta blocker','tachycardia','dose','dosing','onset','duration','delayed peak','off label','asthma','bradycardia','heart block','CAD'],0,true)
