values ('antihypertensive-safety','antihypertensive-dosing','Antihypertensive Dosing','Monitoring & high-risk cautions',array['antihypertensive','antihypertensives','hypertension','HTN','high blood pressure','BP','adult','IV','intravenous','perioperative','periop','postoperative','PACU','monitoring','units','mg','mcg','micrograms','bolus stacking','delayed peak','pain','anesthetic depth','hypercarbia','hypoxia','bradycardia','beta blocker','blood pressure target'],2,true)
on conflict (id) do update set reference_id=excluded.reference_id,
  reference_title=excluded.reference_title,title=excluded.title,keywords=excluded.keywords,
  sort_order=excluded.sort_order,is_published=excluded.is_published;
insert into public.quick_reference_sections (id,body,version)
values ('antihypertensive-safety','| Check | Pertinent detail |
|---|---|
| **Scope** | Adult, monitored perioperative IV reference only; not pediatric, obstetric, stroke, aortic-dissection, or outpatient treatment protocols. Confirm concentration, order, local protocol and patient-specific BP/HR targets. |
| **Treat the cause** | Check pain/anesthetic depth, hypoxemia, hypercarbia, shivering, bladder distension and volume status before simply adding antihypertensives. ([Perioperative BP review](https://pmc.ncbi.nlm.nih.gov/articles/PMC4178624/)) |
| **Units** | Nicardipine/clevidipine: **mg/h**. Labetalol infusion: **mg/min**. Nitroglycerin: **mcg/min**. Esmolol/nitroprusside: **mcg/kg/min**. ([Perioperative dosing table](https://pmc.ncbi.nlm.nih.gov/articles/PMC4178624/)) Verify pump concentration; do not copy mL/h between products. |
| **Beta-blockers** | Monitor ECG, HR and BP; assess for bradycardia, conduction disease, decompensated HF and bronchospasm. Do not treat hypovolemia-related compensatory tachycardia with esmolol. ([Brevibloc label](https://www.accessdata.fda.gov/drugsatfda_docs/label/2023/019386s053lbl.pdf)) |
| **Delayed peak / overshoot** | Hydralazine peak may take **10–80 min**; metoprolol peak about **20 min**. Reassess before repeating and account for all drugs already given. ([Hydralazine label](https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=f1a10203-f027-4f9c-8dd6-907c6db24d47&type=display); [Metoprolol IV manual](https://pdtm.vch.ca/Documents/metoprolol%20NEW.pdf)) |
| **Treatment target** | Avoid abrupt overshoot and preserve organ perfusion; the appropriate reduction depends on the clinical syndrome and baseline BP, not one universal target. ([Perioperative hypertension review](https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/)) |','2026-09-27')
on conflict (id) do update set body=excluded.body,version=excluded.version,updated_at=now();

commit;
